-- Synthetic AI-agent deployment dataset.
-- SYNTHETIC DEMO — not a real customer or deployment
-- Generated by ai_deployment_roi/metrics.py. Do not treat the figures as
-- a customer result. Regenerate this file with build_assets.py.

CREATE TABLE program_assumptions (
    id integer PRIMARY KEY,
    data_label text NOT NULL,
    hourly_rate_usd numeric(12, 2) NOT NULL,
    annual_platform_cost_usd numeric(12, 2) NOT NULL,
    implementation_cost_usd numeric(12, 2) NOT NULL,
    go_live_date date NOT NULL
);

INSERT INTO program_assumptions (
    id, data_label, hourly_rate_usd, annual_platform_cost_usd,
    implementation_cost_usd, go_live_date
) VALUES (
    1, 'SYNTHETIC DEMO — not a real customer or deployment', 85.00, 180000.00,
    75000.00, '2025-07-01'
);

CREATE TABLE agent_monthly_outcomes (
    period_month date NOT NULL,
    team text NOT NULL,
    phase text NOT NULL CHECK (phase IN ('before', 'after')),
    tickets_opened integer NOT NULL,
    tickets_deflected integer NOT NULL,
    tickets_resolved_by_human integer NOT NULL,
    hours_saved numeric(12, 2) NOT NULL,
    cost_per_resolution_usd numeric(12, 2) NOT NULL,
    active_users integer NOT NULL,
    licensed_users integer NOT NULL,
    data_label text NOT NULL,
    PRIMARY KEY (period_month, team),
    CHECK (tickets_deflected >= 0),
    CHECK (tickets_resolved_by_human >= 0),
    CHECK (tickets_deflected + tickets_resolved_by_human = tickets_opened),
    CHECK (active_users <= licensed_users)
);

